// This is just a test, and I haven't been working with GLSL (OpenGL Shading Language) for long.
// Background shader with moving sine wave scroller by melcom (www.melcom-music.de)

void mainImage(out vec4 fragColor, in vec2 fragCoord) {

    // Setzen der Hintergrundfarbe / Set background color
    vec3 bgColor = vec3(0.004, 0.122, 0.153); // Hintergrundfarbe: 011f27 / Background color: 011f27

    // Normierung der Fragmentkoordinaten / Normalize fragment coordinates
    vec2 uv = fragCoord.xy / iResolution.xy;

    // Verschiebung der Wellen nach oben / Shift waves up
    uv.y += 0.2; // Verschiebung der y-Koordinate um 0.2 nach oben / Shift y-coordinate by 0.2 up

    // Berechnung der wellenartigen Bewegung / Calculate wavy movement
    float y = uv.y + 0.1 * sin(uv.x * 10.0 + iTime * 2.0) + 0.05 * sin(uv.y * 5.0 + iTime); // Sinus-Welle mit Bewegung in beiden Richtungen / Sine wave with movement in both directions

    // Farben basierend auf der Sinus-Kurve / Colors based on sine wave
    vec3 color;
    if (y > 0.8) {
        color = vec3(0.173, 0.325, 0.455); // Farbe 1: 2c5374 / Color 1: 2c5374
    } else if (y > 0.6) {
        color = vec3(0.984, 0.388, 0.447); // Farbe 2: fb6372 / Color 2: fb6372
    } else {
        color = vec3(0.988, 0.733, 0.392); // Farbe 3: febb64 / Color 3: febb64
    }

    // Setzen der finalen Fragmentfarbe / Set the final fragment color
    fragColor = vec4(mix(color, bgColor, 0.5), 1.0);
}
